// npm run seed:demo: stores about nine weeks of dummy history (five weeks of briefs plus the 30-day lookback
// before them) in Neon so the dashboard is not empty. Everything is flagged is_demo and clearable with
// `npm run demo:clear`. The shows are the real ones; the guests, companies, episodes and sponsors are invented.
// Briefs are then generated by the REAL weekly pipeline, so this also exercises scoring, narrative and storage.
import { eq, sql } from "drizzle-orm";
import { normalizeGuestKey, normalizeSponsorKey, normalizeTopicLabel } from "@/lib/ai/normalize";
import { COUNTER_ANGLES, SHOWS } from "@/lib/data/mock/fixtures";
import { MOCK_NOW, generateWorld } from "@/lib/data/mock/world";
import { closeDb, db } from "@/lib/db/client";
import {
  briefs,
  episodeGuests,
  episodeSponsors,
  episodeTopics,
  episodes,
  extractions,
  guestAliases,
  guests,
  ingestionLog,
  shows,
  sponsorAliases,
  sponsors,
  topics,
  viewSnapshots,
} from "@/lib/db/schema";
import { runWeeklyAnalysis } from "@/lib/pipeline/weekly";
import { canonicalKey } from "@/lib/sources/match";
import { addDaysISO, startOfDayIST, weekStartIST } from "@/lib/time";
import { printResolved, resolveSeedShows } from "./lib/resolve";

const DAY = 86_400_000;
const NOW = Date.now();
// Keep the weekday structure while moving the sample timeline so it ends at the current Monday.
const SHIFT = startOfDayIST(weekStartIST(NOW)).getTime() - startOfDayIST("2026-10-12").getTime();
const at = (mockMs: number) => mockMs + SHIFT;

async function main() {
  const [{ n }] = (await db().execute(sql`select count(*)::int as n from shows`)).rows as { n: number }[];
  if (n > 0) throw new Error("The database already has shows. Run `npm run demo:clear -- --all` first for a clean demo, or keep what you have.");

  const world = generateWorld("full");
  const resolved = await resolveSeedShows();
  printResolved(resolved);

  /* ---------------- shows with a demo lineup history ---------------- */
  type Row = { id: string; from: number; to: number | null };
  const rowsByName = new Map<string, Row[]>();
  for (const seed of SHOWS) {
    const r = resolved.find((x) => x.name === seed.name)!;
    const c = r.channel;
    for (const iv of seed.intervalsWeeksAgo) {
      const from = at(MOCK_NOW - iv.from * 7 * DAY - DAY / 2);
      const to = iv.to === null ? null : at(MOCK_NOW - iv.to * 7 * DAY - DAY / 2);
      const [row] = await db()
        .insert(shows)
        .values({
          name: seed.name,
          description: (c?.description ?? seed.description).slice(0, 500),
          artworkUrl: c?.thumbnailUrl ?? null,
          youtubeChannelId: c?.id ?? null,
          youtubeUploadsPlaylistId: c?.uploadsPlaylistId ?? null,
          youtubeHandle: c?.handle ?? null,
          youtubeSubscribers: c?.subscribers ?? null,
          spotifyShowId: r.spotify?.id ?? null,
          activeFrom: new Date(from),
          activeTo: to === null ? null : new Date(to),
          // Real discovery must start from now, never re-import what the demo already stands in for.
          lastSeenPublishedAt: to === null ? new Date(NOW) : null,
          lastError: to === null && !c && !r.spotify ? "Nothing to check: no YouTube channel or Spotify show is linked." : null,
        })
        .returning({ id: shows.id });
      rowsByName.set(seed.name, [...(rowsByName.get(seed.name) ?? []), { id: row.id, from, to }]);
    }
  }
  const rowFor = (mockShowId: string, t: number): string => {
    const seed = SHOWS.find((s) => s.id === mockShowId)!;
    const rows = rowsByName.get(seed.name)!;
    return (rows.find((r) => t >= r.from && (r.to === null || t <= r.to)) ?? rows[0]).id;
  };

  /* ---------------- entities ---------------- */
  const lo = MOCK_NOW - 9.5 * 7 * DAY;
  const eps = world.episodes.filter((e) => e.publishedAt >= lo && e.status !== "discovered");
  const usedGuests = new Set(eps.flatMap((e) => e.guestKeys));
  const usedTopics = new Set(eps.flatMap((e) => e.topics));
  const usedSponsors = new Set(eps.flatMap((e) => e.sponsors.map((s) => s.sponsorKey)));

  const guestId = new Map<string, string>();
  for (const g of world.guests.filter((x) => usedGuests.has(x.key))) {
    const key = normalizeGuestKey(g.name);
    await db().insert(guests).values({ canonicalName: g.name, normalizedKey: key, titleOrCompany: g.company }).onConflictDoNothing();
    const [row] = await db().select({ id: guests.id }).from(guests).where(eq(guests.normalizedKey, key));
    guestId.set(g.key, row.id);
    for (const a of g.aliases ?? []) {
      const alias = normalizeGuestKey(a);
      if (alias && alias !== key) await db().insert(guestAliases).values({ guestId: row.id, alias }).onConflictDoNothing();
    }
  }
  const topicId = new Map<string, string>();
  for (const label of usedTopics) {
    const norm = normalizeTopicLabel(label);
    await db().insert(topics).values({ canonicalLabel: norm }).onConflictDoNothing();
    const [row] = await db().select({ id: topics.id }).from(topics).where(eq(topics.canonicalLabel, norm));
    topicId.set(label, row.id);
  }
  const sponsorId = new Map<string, string>();
  for (const s of world.sponsors.filter((x) => usedSponsors.has(x.key))) {
    const key = normalizeSponsorKey(s.name);
    const first = Math.min(...eps.filter((e) => e.sponsors.some((m) => m.sponsorKey === s.key)).map((e) => e.publishedAt));
    await db().insert(sponsors).values({ canonicalName: s.name, normalizedKey: key, firstSeenAt: new Date(at(first)) }).onConflictDoNothing();
    const [row] = await db().select({ id: sponsors.id }).from(sponsors).where(eq(sponsors.normalizedKey, key));
    sponsorId.set(s.key, row.id);
    for (const a of s.aliases ?? []) {
      const alias = normalizeSponsorKey(a);
      if (alias && alias !== key) await db().insert(sponsorAliases).values({ sponsorId: row.id, alias }).onConflictDoNothing();
    }
  }

  /* ---------------- episodes and everything hanging off them ---------------- */
  let inserted = 0;
  for (const e of eps) {
    const published = at(e.publishedAt);
    const seed = SHOWS.find((s) => s.id === e.showId)!;
    const r = resolved.find((x) => x.name === seed.name)!;
    const showRow = rowFor(e.showId, published);
    const guestNames = e.guestKeys.map((k) => world.guests.find((g) => g.key === k)?.name).filter(Boolean);
    const [ep] = await db()
      .insert(episodes)
      .values({
        showId: showRow,
        // Fake id so nothing ever collides with a real video; it is never sent to YouTube (demo rows are skipped).
        youtubeVideoId: e.youtubeUrl ? `demo-${e.id}` : null,
        spotifyEpisodeId: e.spotifyUrl && !e.youtubeUrl ? `demo-${e.id}` : null,
        title: e.title,
        description: `${e.title}.${guestNames.length ? ` Guest: ${guestNames.join(", ")}.` : ""} (Sample episode generated for the demo.)`,
        publishedAt: new Date(published),
        durationSeconds: e.durationMin * 60,
        // Points at the show's real channel so the "YouTube" link opens something real; the video itself is fictional.
        youtubeUrl: e.youtubeUrl && r.channel ? `https://www.youtube.com/channel/${r.channel.id}?demo=1` : null,
        spotifyUrl: null,
        canonicalKey: canonicalKey(e.title, published, seed.name),
        analysisDepth: e.depth,
        status: e.status as "extracted" | "failed" | "skipped",
        statusNote: e.statusNote,
        isDemo: true,
      })
      .returning({ id: episodes.id });
    inserted++;

    if (e.views !== null) {
      await db().insert(viewSnapshots).values([
        { episodeId: ep.id, views: Math.round(e.views * 0.4), capturedAt: new Date(published + DAY) },
        { episodeId: ep.id, views: e.views, capturedAt: new Date(Math.min(NOW, published + 8 * DAY)) },
      ]);
    }
    if (e.status === "extracted") {
      await db().insert(extractions).values({ episodeId: ep.id, model: "demo-seed", rawJson: { demo: true }, confidence: e.depth === "metadata" ? "low" : "high" });
      for (const k of e.guestKeys) await db().insert(episodeGuests).values({ episodeId: ep.id, guestId: guestId.get(k)!, role: "guest" }).onConflictDoNothing();
      for (const label of e.topics) await db().insert(episodeTopics).values({ episodeId: ep.id, topicId: topicId.get(label)!, weight: 1 / e.topics.length }).onConflictDoNothing();
      for (const m of e.sponsors) {
        await db().insert(episodeSponsors).values({
          episodeId: ep.id,
          sponsorId: sponsorId.get(m.sponsorKey)!,
          product: m.product,
          placement: m.placement,
          evidence: m.evidence,
          timestampSeconds: m.timestampSeconds,
          source: m.source,
        });
      }
    } else {
      await db().insert(ingestionLog).values({
        level: e.status === "failed" ? "error" : "warn",
        scope: "episode",
        refId: ep.id,
        refLabel: e.title,
        message: e.status === "failed" ? `Extraction failed: ${e.statusNote}` : (e.statusNote ?? "Skipped"),
        createdAt: new Date(published + 3 * 3_600_000),
      });
    }
  }
  console.log(`Inserted ${inserted} demo episodes, ${guestId.size} guests, ${topicId.size} topics, ${sponsorId.size} sponsors.`);

  /* ---------------- five weekly briefs via the real pipeline ---------------- */
  const angles = Object.fromEntries(Object.entries(COUNTER_ANGLES).map(([k, v]) => [normalizeTopicLabel(k), v]));
  const lastWeek = addDaysISO(weekStartIST(NOW), -7);
  const weeks = Array.from({ length: 5 }, (_, i) => addDaysISO(lastWeek, -7 * (4 - i)));
  for (const w of weeks) {
    const generatedAt = new Date(startOfDayIST(addDaysISO(w, 7)).getTime() + 52 * 60_000);
    const res = await runWeeklyAnalysis(w, { seeding: true, narrative: "gemini", fallbackAngles: angles, generatedAt });
    console.log(`  brief ${w}: ${res.created ? "created" : (res.reason ?? "skipped")}`);
    // Older weeks count as emailed; the latest stays unsent so "Send brief now" can be tried.
    if (w !== lastWeek) await db().update(briefs).set({ sentAt: new Date(generatedAt.getTime() + 6 * 3_600_000 + 12 * 60_000), emailMessageId: "demo" }).where(eq(briefs.weekStart, w));
  }

  await db().insert(ingestionLog).values({ level: "info", scope: "queue", message: "Demo history seeded (5 weeks). Run `npm run demo:clear` to remove it." });
  console.log("\nDone. Open the dashboard to see five weeks of history.");
  await closeDb();
}

main().catch(async (e) => {
  console.error(e);
  await closeDb();
  process.exit(1);
});
